package com.procurement.quotationcomparison.controller;import com.procurement.common.response.*;import com.procurement.quotationcomparison.dto.request.*;import com.procurement.quotationcomparison.dto.response.*;import com.procurement.quotationcomparison.entity.*;import com.procurement.quotationcomparison.service.*;import jakarta.validation.Valid;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/quotation-comparisons")public class QuotationComparisonController{private final QuotationComparisonService s;public QuotationComparisonController(QuotationComparisonService s){this.s=s;}private Pageable p(int a,int b,String c,String d){return PageRequest.of(a,b,Sort.by(Sort.Direction.fromString(d),c));}@PostMapping public ResponseEntity<ApiResponse<QuotationComparisonResponse>>create(@Valid@RequestBody QuotationComparisonRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Comparison created",s.create(r)));}@GetMapping public ApiResponse<PageResponse<QuotationComparisonResponse>>search(@RequestParam(required=false)String keyword,@RequestParam(required=false)ComparisonMethod method,@RequestParam(required=false)ComparisonStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="createdAt")String sort,@RequestParam(defaultValue="desc")String direction){return ApiResponse.success(s.search(keyword,method,status,p(page,size,sort,direction)));}@GetMapping("/search")public ApiResponse<PageResponse<QuotationComparisonResponse>>searchAlias(@RequestParam(required=false)String keyword,@RequestParam(required=false)ComparisonMethod method,@RequestParam(required=false)ComparisonStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="createdAt")String sort,@RequestParam(defaultValue="desc")String direction){return search(keyword,method,status,page,size,sort,direction);}@GetMapping("/{id}")public ApiResponse<QuotationComparisonResponse>get(@PathVariable Long id){return ApiResponse.success(s.get(id));}@PutMapping("/{id}")public ApiResponse<QuotationComparisonResponse>update(@PathVariable Long id,@Valid@RequestBody QuotationComparisonRequest r){return ApiResponse.success("Comparison updated",s.update(id,r));}@DeleteMapping("/{id}")public ResponseEntity<Void>delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}@PostMapping("/{id}/generate")public ApiResponse<QuotationComparisonResponse>generate(@PathVariable Long id){return ApiResponse.success("Comparison generated",s.generate(id));}@PostMapping("/{id}/recommend/{quotationId}")public ApiResponse<QuotationComparisonResponse>recommend(@PathVariable Long id,@PathVariable Long quotationId){return ApiResponse.success("Quotation recommended",s.recommend(id,quotationId));}@PostMapping("/{id}/approve")public ApiResponse<QuotationComparisonResponse>approve(@PathVariable Long id){return ApiResponse.success("Comparison approved",s.approve(id));}@PostMapping("/{id}/reject")public ApiResponse<QuotationComparisonResponse>reject(@PathVariable Long id){return ApiResponse.success("Comparison rejected",s.reject(id));}}
